/// <summary>
/// MPJ_14792_FreezeDefaultFinancialDimensions
/// Class <c>METLedgerJournalTransVendPaymFormDS_Extension</c> holds CoC functionalities regards DS
/// </summary>
[ExtensionOf(FormDatasourcestr(LedgerJournalTransVendPaym, LedgerJournalTrans))]
final class METLedgerJournalTransVendPaymFormDS_Extension
{
}

Method.Source:
/// <summary>
/// Write functionality CoC
/// </summary>
public void  write()
{
    next write();
    this.updateDimensions();
}

    /// <summary>
    /// updates dimension after write. Write method contains update to dimensions.
    /// </summary>
    public void updateDimensions()
    {
        FormDataSource      ds                  = this;
        LedgerJournalTrans  ledgerJournalTrans  = ds.formRun().dataSource(formdataSourceStr(LedgerJournalTransVendPaym, LedgerJournalTrans)).cursor();
        LedgerJournalTable  ledgerJournalTable  = LedgerJournalTable::find(LedgerJournalTrans.JournalNum);
        LedgerJournalName   ledgerJournalName   = LedgerJournalName::find(ledgerJournalTable.journalname);

        if (ledgerJournalName.METFreezeDefaultDimensions == NoYes::Yes)
        {
            ledgerjournaltrans.selectForUpdate(true);
            ledgerjournaltrans.DefaultDimension = ledgerJournalTable.DefaultDimension;
            ledgerjournaltrans.update();
        }       
        
    }
